import { createReadStream } from 'node:fs';
import { mkdir, rename, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { randomToken } from '#shared/crypto/secrets.js';

/**
 * Local disk driver. Layout:
 *   <UPLOAD_DIR>/public/…   served statically at /uploads (Nginx in prod, express.static in dev)
 *   <UPLOAD_DIR>/private/…  never served statically; only through authenticated routes
 * Keys look like "2026/10/k3j…-card.webp" — generated by us, never derived from user input.
 */
const KEY_RE = /^[a-z0-9][a-z0-9/_.-]{0,200}$/i;

export function createLocalDriver({ root }) {
  const base = resolve(root);
  const dirs = { public: resolve(base, 'public'), private: resolve(base, 'private') };

  function pathFor(key, visibility) {
    if (!KEY_RE.test(key) || key.includes('..') || key.includes('//')) {
      throw new Error(`Invalid storage key: ${key}`);
    }
    const dir = dirs[visibility];
    if (!dir) throw new Error(`Invalid visibility: ${visibility}`);
    const full = resolve(dir, key);
    if (!full.startsWith(dir + sep)) throw new Error('Storage key escapes its root');
    return full;
  }

  return {
    name: 'local',
    root: base,
    publicDir: dirs.public,

    /** Atomic write: temp file + rename, so a crash never leaves a half-written file. */
    async put({ key, body, visibility }) {
      const full = pathFor(key, visibility);
      await mkdir(dirname(full), { recursive: true });
      const tmp = `${full}.${randomToken(6)}.tmp`;
      try {
        await writeFile(tmp, body, { flag: 'wx' });
        await rename(tmp, full);
      } catch (err) {
        await rm(tmp, { force: true });
        throw err;
      }
      return { key, bytes: body.length };
    },

    async remove({ key, visibility }) {
      await rm(pathFor(key, visibility), { force: true });
    },

    async stat({ key, visibility }) {
      try {
        const s = await stat(pathFor(key, visibility));
        return { bytes: s.size, modifiedAt: s.mtime };
      } catch (err) {
        if (err.code === 'ENOENT') return null;
        throw err;
      }
    },

    createReadStream({ key, visibility }) {
      return createReadStream(pathFor(key, visibility));
    },
  };
}
